import React, { useState, useEffect } from 'react';
import { getAllRestaurants, getAllUsers } from '../../services/api';
import { useNavigate } from 'react-router-dom';

const RestaurantList = ({ viewMode = 'restaurant' }) => { 
  // 👈 Pass viewMode prop ('restaurant' or 'user')
  const [restaurants, setRestaurants] = useState([]);
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const navigate = useNavigate();

  useEffect(() => {
    loadData();
    const interval = setInterval(loadData, 10000);
    return () => clearInterval(interval);
  }, [viewMode]);

  const loadData = async () => {
    try {
      if (viewMode === 'restaurant') {
        const res = await getAllRestaurants();
        setRestaurants(res.data);
      } else if (viewMode === 'user') {
        const res = await getAllUsers();
        setUsers(res.data);
      }
    } catch (error) {
      console.error('Error loading data:', error);
    } finally {
      setLoading(false);
    }
  };

  // 🔍 Search logic — depends on viewMode
  const filteredRestaurants = restaurants.filter(restaurant =>
    restaurant.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    restaurant.cuisine_type?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    restaurant.address.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const filteredUsers = users.filter(user =>
    user.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    user.email?.toLowerCase().includes(searchTerm.toLowerCase()) ||
    user.role?.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const activeList = viewMode === 'restaurant' ? filteredRestaurants : filteredUsers;

  if (loading) return (
    <div style={styles.loadingContainer}>
      <div style={styles.spinner}></div>
      <p style={styles.loadingText}>Loading {viewMode === 'restaurant' ? 'restaurants' : 'customers'}...</p>
    </div>
  );

  return (
    <div style={styles.container}>
      <div style={styles.hero}>
        <h1 style={styles.heroTitle}>
          {viewMode === 'restaurant' ? 'Discover & Reserve' : 'Customer Management'}
        </h1>
        <p style={styles.heroSubtitle}>
          {viewMode === 'restaurant'
            ? 'Find your perfect dining experience'
            : 'Manage and explore customer profiles'}
        </p>

        {/* 🔍 SAME SEARCH BAR — works for both */}
        <div style={styles.searchContainer}>
          <span style={styles.searchIcon}>🔍</span>
          <input
            type="text"
            placeholder={
              viewMode === 'restaurant'
                ? 'Search by restaurant name, cuisine, or location...'
                : 'Search by customer name, email, or role...'
            }
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            style={styles.searchInput}
          />
          {searchTerm && (
            <button onClick={() => setSearchTerm('')} style={styles.clearBtn}>✕</button>
          )}
        </div>

        {/* Stats bar */}
        <div style={styles.statsBar}>
          <div style={styles.stat}>
            <span style={styles.statNumber}>{activeList.length}</span>
            <span style={styles.statLabel}>
              {viewMode === 'restaurant' ? 'Restaurants' : 'Customers'}
            </span>
          </div>
          <div style={styles.statDivider}></div>
          <div style={styles.stat}>
            <span style={styles.statNumber}>⭐ 4.8</span>
            <span style={styles.statLabel}>Avg Rating</span>
          </div>
        </div>
      </div>

      {/* List */}
      {activeList.length === 0 ? (
        <div style={styles.emptyState}>
          <span style={styles.emptyIcon}>🍽️</span>
          <h2 style={styles.emptyTitle}>
            No {viewMode === 'restaurant' ? 'restaurants' : 'customers'} found
          </h2>
          <p style={styles.emptyText}>
            {searchTerm ? 'Try a different search term' : 'Check back later for updates!'}
          </p>
        </div>
      ) : (
        <div style={styles.grid}>
          {viewMode === 'restaurant'
            ? filteredRestaurants.map((restaurant) => (
                <div
                  key={restaurant.id}
                  style={styles.card}
                  onClick={() => navigate(`/restaurant/${restaurant.id}`)}
                >
                  <div style={styles.imageContainer}>
                    <img
                      src={restaurant.image_url || 'https://via.placeholder.com/400x250?text=Delicious+Food'}
                      alt={restaurant.name}
                      style={styles.image}
                    />
                    <div style={styles.imageBadge}>
                      <span>⭐ 4.8</span>
                    </div>
                  </div>

                  <div style={styles.cardContent}>
                    <h3 style={styles.restaurantName}>{restaurant.name}</h3>
                    <p style={styles.cuisine}>✨ {restaurant.cuisine_type}</p>
                    <p style={styles.infoItem}>📍 {restaurant.address}</p>
                    <p style={styles.infoItem}>🕒 {restaurant.opening_time} - {restaurant.closing_time}</p>
                    <button style={styles.viewBtn}>View Details & Reserve →</button>
                  </div>
                </div>
              ))
            : filteredUsers.map((user) => (
                <div key={user.id} style={styles.card}>
                  <div style={styles.cardContent}>
                    <h3 style={styles.restaurantName}>{user.name}</h3>
                    <p style={styles.cuisine}>📧 {user.email}</p>
                    <p style={styles.infoItem}>👤 Role: {user.role}</p>
                  </div>
                </div>
              ))}
        </div>
      )}
    </div>
  );
};

